import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route('**/font/**', r=>r.abort())
await p.route('**/*.woff2*', r=>r.abort())
await p.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2000)
const inputs = p.locator('input'); const n = await inputs.count()
for(let i=0;i<n;i++){ const t=await inputs.nth(i).getAttribute('type'); if(t==='checkbox') await inputs.nth(i).check(); else await inputs.nth(i).fill(i===0?'admin':'x123456') }
await p.getByRole('button',{name:'登录',exact:true}).click(); await p.waitForTimeout(1500)
await p.getByText('物业手持端',{exact:false}).first().click(); await p.waitForTimeout(1500)
await p.getByText('数智',{exact:true}).first().click(); await p.waitForTimeout(1500)

// dump all svg outerHTML with their parent context
const svgs = await p.evaluate(()=>{
  return [...document.querySelectorAll('svg')].map(s=>{
    const r=s.getBoundingClientRect(); const cs=getComputedStyle(s)
    return {w:Math.round(r.width),h:Math.round(r.height),y:Math.round(r.y),color:cs.color,fill:cs.fill,html:s.outerHTML.slice(0,800)}
  })
})
console.log('SVGCOUNT',svgs.length)
svgs.forEach((s,i)=>console.log(`--- SVG ${i} w=${s.w} h=${s.h} y=${s.y} color=${s.color} fill=${s.fill}\n${s.html}`))

// dump metric-panel structure & colors
const panels = await p.evaluate(()=>{
  const out=[]
  document.querySelectorAll('*').forEach(el=>{
    const cs=getComputedStyle(el); const r=el.getBoundingClientRect()
    if(r.height>60 && r.width>300 && (cs.borderRadius.includes('px')) && el.children.length>0){
      const t=(el.className||'').toString()
      if(/panel|card|metric/.test(t)) out.push({cls:t,y:Math.round(r.y),h:Math.round(r.height),bg:cs.backgroundColor,br:cs.borderRadius,pad:cs.padding,shadow:cs.boxShadow.slice(0,60)})
    }
  })
  return out
})
console.log('=== PANELS ===')
panels.forEach(x=>console.log(JSON.stringify(x)))
await browser.close()

import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route('**/font/**', r=>r.abort())
await p.route('**/*.woff2*', r=>r.abort())
await p.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2000)
const inputs = p.locator('input'); const n = await inputs.count()
for(let i=0;i<n;i++){ const t=await inputs.nth(i).getAttribute('type'); if(t==='checkbox') await inputs.nth(i).check(); else await inputs.nth(i).fill(i===0?'admin':'x123456') }
await p.getByRole('button',{name:'登录',exact:true}).click(); await p.waitForTimeout(1500)
await p.getByText('物业手持端',{exact:false}).first().click(); await p.waitForTimeout(1500)
await p.getByText('数智',{exact:true}).first().click(); await p.waitForTimeout(1500)

const res = await p.evaluate(()=>{
  const gcb=(el)=>{const c=getComputedStyle(el);return {cls:(el.className||'').toString(),tag:el.tagName.toLowerCase(),color:c.color,fs:c.fontSize,fw:c.fontWeight,ff:c.fontFamily.slice(0,40),bg:c.backgroundColor,br:c.borderRadius,pad:c.padding,gap:c.gap,disp:c.display,gtc:c.gridTemplateColumns}}
  const out={}
  // metric-panel green inner
  const panel=document.querySelector('.metric-panel.green')
  out.panelGreenHTML = panel.innerHTML.slice(0,2000)
  // find icon element (first child of header)
  const icon = panel.querySelector('[class*=icon], i, .metric-icon')
  out.iconOuter = icon ? icon.outerHTML.slice(0,500) : 'NONE'
  out.iconCls = icon ? gcb(icon) : null
  // key text els
  const els=panel.querySelectorAll('*')
  out.panelTexts=[...els].filter(e=>e.children.length===0 && e.textContent.trim()).slice(0,12).map(e=>({t:e.textContent.trim().slice(0,20),...gcb(e)}))
  // section title
  const st=[...document.querySelectorAll('*')].find(e=>/section-title|section-head/.test((e.className||'').toString()) && e.textContent.includes('关键数据指标'))
  if(st){out.sectionHTML=st.outerHTML.slice(0,900); out.sectionCls=gcb(st)}
  // mini metric cell
  const mini=panel.querySelector('.metric-breakdown').children[0]
  out.miniHTML=mini.outerHTML.slice(0,400); out.miniCls=gcb(mini)
  const miniTxt=[...mini.querySelectorAll('*')].map(e=>({t:e.textContent.trim().slice(0,14),...gcb(e)}))
  out.miniTxt=miniTxt.slice(0,6)
  // pill row
  const pills=[...document.querySelectorAll('*')].filter(e=>e.textContent.trim()==='全市数据' && e.children.length===0)[0]
  let pp=pills; while(pp && !/pill|tab|region/.test((pp.className||'').toString())) pp=pp.parentElement
  if(pp){out.pillHTML=pp.outerHTML.slice(0,800);out.pillCls=gcb(pp)}
  return out
})
console.log(JSON.stringify(res,null,1).slice(0,7000))
await browser.close()

import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route('**/font/**', r=>r.abort()); await p.route('**/*.woff2*', r=>r.abort())
await p.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2000)
const inputs = p.locator('input'); const n = await inputs.count()
for(let i=0;i<n;i++){ const t=await inputs.nth(i).getAttribute('type'); if(t==='checkbox') await inputs.nth(i).check(); else await inputs.nth(i).fill(i===0?'admin':'x123456') }
await p.getByRole('button',{name:'登录',exact:true}).click(); await p.waitForTimeout(1500)
await p.getByText('物业手持端',{exact:false}).first().click(); await p.waitForTimeout(1500)
await p.getByText('数智',{exact:true}).first().click(); await p.waitForTimeout(1500)
const res = await p.evaluate(()=>{
  const g=(el)=>{if(!el)return null;const c=getComputedStyle(el);return{tag:el.tagName.toLowerCase(),fs:c.fontSize,fw:c.fontWeight,color:c.color,bg:c.backgroundColor,br:c.borderRadius,pad:c.padding,gap:c.gap,disp:c.display,gtc:c.gridTemplateColumns,gt:el.textContent.trim().slice(0,16)}}
  const out={}
  // metric header span title color per panel
  out.headers=[...document.querySelectorAll('.metric-panel')].map(pn=>{const s=pn.querySelector('header span');return {cls:(pn.className),color:s?getComputedStyle(s).color:null,img:pn.querySelector('header img')?.getAttribute('src')}})
  // big number color per panel
  out.nums=[...document.querySelectorAll('.metric-panel')].map(pn=>{const s=pn.querySelector('header strong');return {cls:pn.className,color:s?getComputedStyle(s).color:null,fs:s?getComputedStyle(s).fontSize:null}})
  // mini-metric cell css
  out.mini=g(document.querySelector('.mini-metric'))
  // metric-breakdown grid
  out.bd=g(document.querySelector('.metric-breakdown'))
  // pill row container
  const regionBtns=[...document.querySelectorAll('button')].filter(b=>b.textContent.trim()==='全市数据')
  out.pillSel=g(regionBtns[0])
  let row=regionBtns[0]?.parentElement; out.pillRow=g(row); out.pillRowHTML=row?row.outerHTML.slice(0,700):null
  // section-heading h2 style + accent via ::before? get h2
  const h2=document.querySelector('.section-heading h2'); out.h2=g(h2)
  const h2before=h2?getComputedStyle(h2,'::before'):null; out.h2before=h2before?{content:h2before.content,w:h2before.width,bg:h2before.backgroundColor,br:h2before.borderRadius,ml:h2before.marginLeft,mr:h2before.marginRight}:null
  // section-heading right button (全市数据 gray text)
  out.headBtn=g(document.querySelector('.section-heading button'))
  // pill toggle (当月数据/图表趋势)
  const toggle=[...document.querySelectorAll('.section-heading, .section-toggle')].map(()=>null)
  const monthBtn=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='当月数据'); out.monthBtn=g(monthBtn); out.monthBtnRow=g(monthBtn?.parentElement)
  // evaluation card structure
  const ec=document.querySelector('.evaluation-card'); out.ecHTML=ec?ec.innerHTML.slice(0,1200):null
  // evaluation progress bar
  const bar=ec?.querySelector('[class*=bar],[class*=progress]'); out.bar=g(bar); out.barHTML=bar?bar.outerHTML.slice(0,500):null
  // ranking table
  const rc=document.querySelector('.ranking-card'); out.rankHTML=rc?rc.innerHTML.slice(0,1500):null
  // donut
  const dash=document.querySelector('.dashboard-card:nth-of-type(2) , .dashboard-card')
  const donut=[...document.querySelectorAll('.dashboard-card')].find(d=>d.textContent.includes('14,860') && d.querySelector('[class*=donut],[class*=ring],[class*=chart]'))
  out.donutFound=!!donut
  if(donut){const de=donut.querySelector('[class*=donut],[class*=ring],[class*=chart],[style*=conic]'); out.donutHTML=de?de.outerHTML.slice(0,600):donut.innerHTML.slice(-800)}
  return out
})
console.log(JSON.stringify(res,null,1))
await browser.close()

import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route('**/font/**', r=>r.abort()); await p.route('**/*.woff2*', r=>r.abort())
await p.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2000)
const inputs = p.locator('input'); const n = await inputs.count()
for(let i=0;i<n;i++){ const t=await inputs.nth(i).getAttribute('type'); if(t==='checkbox') await inputs.nth(i).check(); else await inputs.nth(i).fill(i===0?'admin':'x123456') }
await p.getByRole('button',{name:'登录',exact:true}).click(); await p.waitForTimeout(1500)
await p.getByText('物业手持端',{exact:false}).first().click(); await p.waitForTimeout(1500)
await p.getByText('数智',{exact:true}).first().click(); await p.waitForTimeout(1500)
const res = await p.evaluate(()=>{
  const out={}
  const sh=document.querySelector('.section-heading'); const sc=getComputedStyle(sh)
  out.headingFull={borderLeft:sc.borderLeft,padLeft:sc.paddingLeft,bg:sc.backgroundColor,margin:sc.margin,padding:sc.padding,h:sh.getBoundingClientRect().height,display:sc.display,justify:sc.justifyContent,align:sc.alignItems,gap:sc.gap}
  // maybe accent is a pseudo on h2 or a child. check h2 border
  const h2=document.querySelector('.section-heading h2'); const h2c=getComputedStyle(h2)
  out.h2full={borderLeft:h2c.borderLeft,padLeft:h2c.paddingLeft,color:h2c.color,fs:h2c.fontSize,fw:h2c.fontWeight,lh:h2c.lineHeight}
  // donut style
  const donut=document.querySelector('.donut'); const dc=getComputedStyle(donut)
  out.donut={bg:dc.backgroundImage||dc.background, w:donut.getBoundingClientRect().width, h:donut.getBoundingClientRect().height, br:dc.borderRadius, mask:dc.mask,webkitMask:dc.webkitMask}
  // donut inner
  out.donutHTML=donut.outerHTML.slice(0,600)
  const dn=donut.querySelector('span'),dd=donut.querySelector('strong')
  out.donutTxt={span:{fs:getComputedStyle(dn).fontSize,color:getComputedStyle(dn).color},strong:{fs:getComputedStyle(dd).fontSize,fw:getComputedStyle(dd).fontWeight,color:getComputedStyle(dd).color}}
  // four-metrics grid (公共收益)
  const fm=document.querySelector('.four-metrics'); const fc=getComputedStyle(fm)
  out.four={disp:fc.display,gtc:fc.gridTemplateColumns,gap:fc.gap}
  out.fourHTML=fm.innerHTML.slice(0,600)
  // mini-metric variants colors
  const mm=document.querySelectorAll('.mini-metric')
  const seen={}
  mm.forEach(el=>{const c=el.className; if(!seen[c]){const s=el.querySelector('strong');const sp=el.querySelector('span');seen[c]={bg:getComputedStyle(el).backgroundColor,numColor:s?getComputedStyle(s).color:null,numFs:s?getComputedStyle(s).fontSize:null,lblColor:sp?getComputedStyle(sp).color:null,lblFs:sp?getComputedStyle(sp).fontSize:null,pad:getComputedStyle(el).padding,br:getComputedStyle(el).borderRadius}}})
  out.miniVariants=seen
  // progress-line i colors
  const pl=document.querySelector('.progress-line'); out.pl={disp:getComputedStyle(pl).display,h:pl.getBoundingClientRect().height,gap:getComputedStyle(pl).gap}
  out.plChildren=[...pl.querySelectorAll('i')].map(i=>({bg:getComputedStyle(i).backgroundColor,flex:getComputedStyle(i).flex}))
  // metric-panel header img size
  const im=document.querySelector('.metric-panel header img'); out.iconImg={w:im.getBoundingClientRect().width,h:im.getBoundingClientRect().height}
  // header strong font-family mono check
  const hs=document.querySelector('.metric-panel header strong'); out.bigFont=getComputedStyle(hs).fontFamily.slice(0,50)
  // region-tabs button (non-active) style
  const nb=[...document.querySelectorAll('.region-tabs button')][1]; out.regionBtn={bg:getComputedStyle(nb).backgroundColor,color:getComputedStyle(nb).color,h:nb.getBoundingClientRect().height,br:getComputedStyle(nb).borderRadius,pad:getComputedStyle(nb).padding,fs:getComputedStyle(nb).fontSize}
  // scroll wrapper classes
  out.bodybg=getComputedStyle(document.body).backgroundColor
  return out
})
console.log(JSON.stringify(res,null,1))
await browser.close()

